    if not input_unchanged:
        raise RuntimeError('Frozen mechanical input was modified.')
    original = Path('input.md').read_text()
    source_unchanged = hashlib.sha256(Path('input.md').read_bytes()).hexdigest() == '3d2f9ed7390e247b388dfd62ae735272c4c35adab5f471f922046dc9ef93e7a2'
    if not source_unchanged:
        raise RuntimeError('Original source was modified.')
    final = output_path.read_text()
    with tempfile.TemporaryDirectory(prefix='redline-final-measure-', dir=scratch) as command_dir:
        env = dict(os.environ, TMPDIR=command_dir)
        result = subprocess.run(['uv','run','--no-cache','--no-project',str(Path('.agents/skills/kntnt/library/scripts/article_anatomy.py').resolve()),'-'],input=final,text=True,env=env,capture_output=True)
